package com.kodeboxx.smartintake.application;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.kodeboxx.smartintake.contract.CsvSafety;
import com.kodeboxx.smartintake.contract.FormRuntime;
import com.kodeboxx.smartintake.contract.PackageStamp;
import com.kodeboxx.smartintake.compatibility.RespondentSecretVerifier;
import com.kodeboxx.smartintake.persistence.AuditEventRepository;
import com.kodeboxx.smartintake.security.StaffAuthorization;
import java.time.*;
import java.util.*;
import org.springframework.http.*;
import org.springframework.jdbc.core.*;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.stereotype.Service;
import org.springframework.web.server.ResponseStatusException;

@Service
public class IntakeApplicationService {
 private final JdbcTemplate db; private final ObjectMapper json; private final StaffAuthorization authorization; private final AuditEventRepository audits; private final RespondentSecretVerifier respondentSecrets;
 public IntakeApplicationService(JdbcTemplate db,ObjectMapper json,StaffAuthorization authorization,AuditEventRepository audits,RespondentSecretVerifier respondentSecrets){this.db=db;this.json=json;this.authorization=authorization;this.audits=audits;this.respondentSecrets=respondentSecrets;}
 public record Bootstrap(String email,String password,String organizationName,String workspaceName){} public record CreateForm(String formKey,String title){} public record Draft(Map<String,Object> definition){} public record StartSession(String locale,String timeZone){} public record PatchSession(Long baseRevision,UUID clientMutationId,Map<String,Object> answers){} public record Submit(Long sessionRevision){} public ResponseEntity<?> bootstrap(Bootstrap in){if(in.email()==null||!in.email().contains("@")||in.password()==null||in.password().length()<12)throw bad("BOOTSTRAP_INVALID","Email and 12+ character password required");if(db.queryForObject("select count(*) from accounts",Integer.class)!=0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Bootstrap closed");UUID a=UUID.randomUUID(),o=UUID.randomUUID(),w=UUID.randomUUID(),t=UUID.randomUUID();db.update("insert into accounts(id,email,password_hash) values(?,?,?)",a,in.email().toLowerCase(),new BCryptPasswordEncoder().encode(in.password()));db.update("insert into organizations(id,name) values(?,?)",o,Optional.ofNullable(in.organizationName()).orElse("Local organization"));db.update("insert into workspaces(id,organization_id,workspace_key,name) values(?,?,?,?)",w,o,"local",Optional.ofNullable(in.workspaceName()).orElse("Local workspace"));db.update("insert into memberships(account_id,workspace_id,role) values(?,?,?)",a,w,"OWNER");db.update("insert into staff_sessions(token,account_id,expires_at) values(?,?,?)",t,a,java.sql.Timestamp.from(Instant.now().plus(Duration.ofHours(8))));audit("BOOTSTRAP_COMPLETED",a);return ResponseEntity.status(201).body(Map.of("staffSession",t.toString(),"workspaceKey","local","roles",List.of("OWNER")));} public ResponseEntity<?> signIn(Bootstrap in){try{var a=db.queryForMap("select id,password_hash from accounts where email=?",in.email().toLowerCase(Locale.ROOT));if(!new BCryptPasswordEncoder().matches(in.password(),(String)a.get("password_hash")))throw new IllegalArgumentException();UUID t=UUID.randomUUID();db.update("insert into staff_sessions(token,account_id,expires_at) values(?,?,?)",t,a.get("id"),java.sql.Timestamp.from(Instant.now().plus(Duration.ofHours(8))));return ResponseEntity.ok(Map.of("staffSession",t.toString(),"workspaceKey","local"));}catch(Exception e){throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials");}} public ResponseEntity<?> logout(String token){try{if(token!=null)db.update("delete from staff_sessions where token=?",UUID.fromString(token));}catch(Exception ignored){}return ResponseEntity.noContent().build();} public Map<String,Object> health(){return Map.of("status","UP","service","smart-intake-api","contractVersion","4.0.0");} public Map<String,Object> capabilities(){return Map.of("contractVersion","4.0.0","fieldTypes",List.of("text","integer","decimal","boolean","choice","multiChoice","date","object","list","attachments","drawing"),"operators",List.of("equals","notEquals","isAnswered","greaterThan","contains"));} public List<Map<String,Object>> forms(String workspace,String token){UUID ws=authorization.authorize(workspace,token);return db.query("select id,form_key,title,status,revision,updated_at from forms where workspace_id=? order by updated_at desc",(rs,n)->Map.of("id",rs.getObject("id").toString(),"formKey",rs.getString("form_key"),"title",rs.getString("title"),"status",rs.getString("status"),"revision",rs.getLong("revision"),"updatedAt",rs.getObject("updated_at").toString()),ws);} public ResponseEntity<?> create(String workspace,String token,CreateForm in){UUID ws=authorization.authorize(workspace,token);if(in.formKey()==null||!in.formKey().matches("[a-z][a-z0-9-]{2,99}"))throw bad("FORM_KEY_INVALID","Use a lowercase stable key of at least three characters."); UUID id=UUID.randomUUID();Map<String,Object> def=sampleDefinition(in.formKey(),in.title());db.update("insert into forms(id,workspace_id,form_key,title,definition) values(?,?,?,?,cast(? as jsonb))",id,ws,in.formKey(),in.title(),stringify(def));audit("FORM_CREATED",id);return ResponseEntity.status(201).eTag(etag(1)).body(Map.of("id",id,"draftId",id,"revision",1,"definition",def));} public ResponseEntity<?> draft(String workspace,UUID form,String token){authorization.requireOwnedForm(workspace,token,form);var row=formRow(form);return ResponseEntity.ok().eTag(etag(row.revision())).body(Map.of("id",form,"revision",row.revision(),"definition",parse(row.definition()),"diagnostics",List.of()));} public ResponseEntity<?> save(String workspace,UUID form,String token,String match,Draft in){authorization.requireOwnedForm(workspace,token,form);var row=formRow(form);if(match==null)throw new ResponseStatusException(HttpStatus.PRECONDITION_REQUIRED,"If-Match required");if(!match.equals(etag(row.revision())))throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Draft changed; reload to resolve conflict"); validateDefinition(in.definition());long next=row.revision()+1;db.update("update forms set definition=cast(? as jsonb), revision=?, updated_at=now() where id=?",stringify(in.definition()),next,form);audit("DRAFT_SAVED",form);return ResponseEntity.ok().eTag(etag(next)).body(Map.of("revision",next,"definition",in.definition(),"diagnostics",List.of()));} public Map<String,Object> definitionExport(String workspace,UUID form,String token){authorization.requireOwnedForm(workspace,token,form);return json.convertValue(PackageStamp.attach(json.valueToTree(parse(formRow(form).definition())),"lite-expression-1","tzdb-system"),Map.class);} public ResponseEntity<?> definitionImport(String workspace,UUID form,String token,String match,Map<String,Object> candidate){authorization.requireOwnedForm(workspace,token,form);var row=formRow(form);if(match==null||!match.equals(etag(row.revision())))throw new ResponseStatusException(HttpStatus.PRECONDITION_FAILED,"Draft changed; reload before import");try{PackageStamp.verify(json.valueToTree(candidate));candidate.remove("packageStamp");validateDefinition(candidate);}catch(Exception e){return ResponseEntity.unprocessableEntity().body(Map.of("code","IMPORT_INVALID","diagnostics",List.of(Map.of("message",e.getMessage()))));}long revision=row.revision()+1;db.update("update forms set definition=cast(? as jsonb),revision=?,updated_at=now() where id=?",stringify(candidate),revision,form);audit("DEFINITION_IMPORTED",form);return ResponseEntity.ok().eTag(etag(revision)).body(Map.of("revision",revision,"diagnostics",List.of()));} public ResponseEntity<?> publish(String workspace,UUID form,String token){authorization.requireOwnedForm(workspace,token,form);var row=formRow(form);validateDefinition(parse(row.definition()));int version=db.queryForObject("select coalesce(max(version),0)+1 from form_releases where form_id=?",Integer.class,form);UUID release=UUID.randomUUID();db.update("insert into form_releases(id,form_id,version,package) values(?,?,?,cast(? as jsonb))",release,form,version,row.definition());db.update("update forms set status='PUBLISHED',updated_at=now() where id=?",form);audit("FORM_PUBLISHED",form);return ResponseEntity.status(201).body(Map.of("releaseId",release,"version",version,"shareId",form.toString(),"status","PUBLISHED"));} public ResponseEntity<?> start(UUID share,StartSession in){R release=latestRelease(share);UUID id=UUID.randomUUID(),secret=UUID.randomUUID();String locale=in==null||in.locale()==null?"en":in.locale();db.update("insert into sessions(id,form_id,release_id,respondent_token,respondent_secret_sha256,locale,answers) values(?,?,?,?,?,?,cast('{}' as jsonb))",id,share,release.id(),secret,respondentSecrets.digest(secret),locale);return ResponseEntity.status(201).body(Map.of("sessionId",id,"respondentSession",secret,"revision",0,"locale",locale,"release",parse(release.pkg()),"expiresAt",Instant.now().plus(Duration.ofDays(7)).toString()));} public Map<String,Object> session(UUID id,String token){return sessionView(respondent(id,token));} public Map<String,Object> patch(UUID id,String token,PatchSession in){var s=respondent(id,token);if(in.clientMutationId()==null)throw bad("MUTATION_ID_REQUIRED","clientMutationId required");try{return parse(db.queryForObject("select response::text from session_mutations where session_id=? and client_mutation_id=?",String.class,id,in.clientMutationId()));}catch(Exception ignored){}if(!s.status().equals("DRAFT"))throw bad("SESSION_CLOSED","Submitted");if(!Objects.equals(in.baseRevision(),s.revision()))throw new ResponseStatusException(HttpStatus.CONFLICT,"SESSION_REVISION_CONFLICT");Map<String,Object> answers=new FormRuntime(json).respondentAnswers(parse(release(s.releaseId()).pkg()),in.answers());long next=s.revision()+1;Map<String,Object> out=Map.of("acceptedRevision",next,"answers",answers,"validation",validateAnswers(release(s.releaseId()).pkg(),answers));db.update("update sessions set answers=cast(? as jsonb),revision=? where id=?",stringify(answers),next,id);db.update("insert into session_mutations(session_id,client_mutation_id,accepted_revision,response) values(?,?,?,cast(? as jsonb))",id,in.clientMutationId(),next,stringify(out));return out;} public Map<String,Object> validate(UUID id,String token){var s=respondent(id,token);return Map.of("errors",validateAnswers(release(s.releaseId()).pkg(),parse(s.answers())),"reviewDigest",UUID.nameUUIDFromBytes(s.answers().getBytes()).toString());} public ResponseEntity<?> submit(UUID id,String token,Submit in){var s=respondent(id,token);if(!Objects.equals(in.sessionRevision(),s.revision()))throw new ResponseStatusException(HttpStatus.CONFLICT,"REVIEW_STALE");var errors=validateAnswers(release(s.releaseId()).pkg(),parse(s.answers()));if(!errors.isEmpty())return ResponseEntity.unprocessableEntity().body(Map.of("code","VALIDATION_FAILED","errors",errors));UUID sub=UUID.randomUUID();Map<String,Object> envelope=Map.of("contractVersion","4.0.0","submissionId",sub,"formId",s.formId(),"answers",parse(s.answers()),"submittedAt",Instant.now().toString());db.update("insert into submissions(id,form_id,session_id,envelope) values(?,?,?,cast(? as jsonb))",sub,s.formId(),id,stringify(envelope));db.update("update sessions set status='SUBMITTED' where id=?",id);audit("SUBMISSION_ACCEPTED",sub);return ResponseEntity.status(201).body(Map.of("receiptId",sub,"submissionId",sub,"message","Your response has been received."));} public List<Map<String,Object>> submissions(String workspace,String token){UUID ws=authorization.authorize(workspace,token);return db.query("select s.id,s.form_id,s.submitted_at from submissions s join forms f on f.id=s.form_id where f.workspace_id=? order by s.submitted_at desc",(rs,n)->Map.of("id",rs.getObject("id").toString(),"formId",rs.getObject("form_id").toString(),"submittedAt",rs.getObject("submitted_at").toString()),ws);} public Object submission(String workspace,UUID id,String token){UUID ws=authorization.authorize(workspace,token);try{return parse(db.queryForObject("select s.envelope::text from submissions s join forms f on f.id=s.form_id where s.id=? and f.workspace_id=?",String.class,id,ws));}catch(Exception e){throw missing();}} public List<Map<String,Object>> jsonExport(String workspace,String token){UUID ws=authorization.authorize(workspace,token);return db.query("select s.envelope::text from submissions s join forms f on f.id=s.form_id where f.workspace_id=? order by s.submitted_at desc",(rs,n)->parse(rs.getString(1)),ws);} public String csv(String workspace,String token){UUID ws=authorization.authorize(workspace,token);StringBuilder b=new StringBuilder("submission_id,form_id,submitted_at,answers\n");db.query("select s.id,s.form_id,s.submitted_at,s.envelope->'answers' answers from submissions s join forms f on f.id=s.form_id where f.workspace_id=? order by s.submitted_at desc",(org.springframework.jdbc.core.RowCallbackHandler)rs->b.append(CsvSafety.cell(rs.getObject("id"))).append(',').append(CsvSafety.cell(rs.getObject("form_id"))).append(',').append(CsvSafety.cell(rs.getObject("submitted_at"))).append(',').append(CsvSafety.cell(rs.getString("answers"))).append("\n"),ws);return b.toString();}
 private record F(UUID id,long revision,String definition){} private record R(UUID id,String pkg){} private record S(UUID id,UUID formId,UUID releaseId,long revision,String answers,String status){}
 private R release(UUID id){return db.queryForObject("select id,package::text from form_releases where id=?",(rs,n)->new R((UUID)rs.getObject(1),rs.getString(2)),id);} private S respondent(UUID id,String token){try{if(token==null)throw new Exception();UUID secret=UUID.fromString(token);return db.queryForObject("select id,form_id,release_id,revision,answers::text,status,respondent_secret_sha256,respondent_token from sessions where id=? and expires_at>now()",(rs,n)->{String digest=rs.getString(7);if(digest==null){UUID legacy=(UUID)rs.getObject(8);if(!secret.equals(legacy))throw new IllegalArgumentException();digest=respondentSecrets.digest(secret);db.update("update sessions set respondent_secret_sha256=? where id=? and respondent_secret_sha256 is null",digest,id);}if(!respondentSecrets.matches(secret,digest))throw new IllegalArgumentException();return new S((UUID)rs.getObject(1),(UUID)rs.getObject(2),(UUID)rs.getObject(3),rs.getLong(4),rs.getString(5),rs.getString(6));},id);}catch(Exception e){throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Respondent session required");}} private R latestRelease(UUID form){try{return db.queryForObject("select id,package::text from form_releases where form_id=? order by version desc limit 1",(rs,n)->new R((UUID)rs.getObject(1),rs.getString(2)),form);}catch(Exception e){throw new ResponseStatusException(HttpStatus.NOT_FOUND,"No published release");}} private F formRow(UUID id){try{return db.queryForObject("select id,revision,definition::text from forms where id=?",(rs,n)->new F((UUID)rs.getObject(1),rs.getLong(2),rs.getString(3)),id);}catch(Exception e){throw missing();}}
 private S sessionRow(UUID id){try{return db.queryForObject("select id,form_id,release_id,revision,answers::text,status from sessions where id=?",(rs,n)->new S((UUID)rs.getObject(1),(UUID)rs.getObject(2),(UUID)rs.getObject(3),rs.getLong(4),rs.getString(5),rs.getString(6)),id);}catch(Exception e){throw missing();}}
 private Map<String,Object> sessionView(S s){Map<String,Object> definition=parse(release(s.releaseId()).pkg());return Map.of("sessionId",s.id(),"revision",s.revision(),"answers",new FormRuntime(json).calculatedAnswers(definition,parse(s.answers())),"status",s.status(),"definition",definition);}
 @SuppressWarnings("unchecked") private Map<String,Object> parse(String s){try{return json.readValue(s,Map.class);}catch(Exception e){throw new IllegalArgumentException(e);}} private String stringify(Object o){try{return json.writeValueAsString(o);}catch(Exception e){throw new IllegalArgumentException(e);}}
 private Map<String,Object> sampleDefinition(String key,String title){
   Map<String,Object> name=Map.of("id","full-name","type","text","label","Your full name","required",true);
   Map<String,Object> contact=Map.of("id","contact-method","type","choice","label","Preferred contact method","required",true,"options",List.of(Map.of("id","email","label","Email"),Map.of("id","phone","label","Phone")));
   Map<String,Object> email=Map.of("id","email-address","type","text","label","Email address","required",true,"visibleWhen",Map.of("fieldId","contact-method","equals","email"));
   return Map.of("contractVersion","4.0.0","formKey",key,"title",title,"pages",List.of(Map.of("id","page-intake","title","Tell us about yourself","fields",List.of(name,contact,email))));
 }
 private void validateDefinition(Map<String,Object> d){try{new FormRuntime(json).validateDefinition(d);}catch(IllegalArgumentException e){throw bad(e.getMessage(),"Invalid field registry, page, or rule AST.");}}
 private List<Map<String,Object>> validateAnswers(String definition,Map<String,Object> answers){return new FormRuntime(json).validate(parse(definition),answers);}
 private void audit(String a,UUID id){audits.record(a,id);}private String etag(long rev){return "\""+rev+"\"";}private ResponseStatusException bad(String c,String d){return new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,c+": "+d);}private ResponseStatusException missing(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"Resource not found");}
}
